use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        let plank_opt = planks.get(index: i);
        match plank_opt {
            Some(plank) => {
                if rules.keeps(plank: plank) {
                    let label = rules.label(plank: plank);
                    labels.push(item: label);
                }
            }
            None => {}
        }
        i = i + 1;
    }
    return labels.join(sep: ",");
}

