use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = match frames.get(index: i) {
            Some(f) => f,
            None => "",
        };
        let decoded = feed.decode(frame: frame);
        let value = match decoded {
            Ok(n) => n,
            Err(_) => 0,
        };
        total = total + value;
        i = i + 1;
    }
    feed.emit(io: io, total: total)?;
    return Ok(unit);
}

