use harbor.signal;

pub fn entries() -> String {
    let signals = signal.sequence();
    var result = "";
    var i = 0;
    while i < signals.len() {
        let s = match signals.get(index: i) {
            Some(v) => v,
            None => signal.Signal.Calm,
        };
        let part = match s {
            signal.Signal.Calm => "calm",
            signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            signal.Signal.Fog(density) => "fog:".concat(other: density),
        };
        if i == 0 {
            result = part;
        } else {
            result = result.concat(other: ";").concat(other: part);
        }
        i = i + 1;
    }
    return result;
}

