use stable.herd::{lineup, feed};
use stable.ledger::entry;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < ponies.len() {
        let pony = ponies.get(index: i)?;
        let fed = feed(pony: pony, scoops: 3);
        let e = entry(pony: fed);
        entries.push(item: e);
        i = i + 1;
    }
    let joined = entries.join(sep: ", ");
    io.write(text: joined)?;
    return Ok(unit);
}

